  display: flex;
  flex-direction: column;
  gap: var(--instui-space-medium);
}

div[class~="pfx-two-column"] .pfx-divider {
  display: none;
}

div[class~="pfx-two-column"] .pfx-divider.-visible {
  display: block;
  width: 1px;
  background-color: var(--instui-color-border);
}

@media (max-width: 768px) {
  div[class~="pfx-two-column"] {
    grid-template-columns: 1fr;
    gap: var(--instui-space-medium);
