{"content": "/**
 * Extract i18n-candidate strings from :slot() pseudo-elements in layout CSS.
 * Finds placeholder text that should be translated and cached.
 */

/**
 * Extracted slot placeholder information.
 */
export interface SlotPlaceholder {
  slotName: string;
