 * @part .pfx-header - Top header region.
 * @part .pfx-body - Main body containing sidebar and content.
 * @part .pfx-sidebar - Left navigation or auxiliary column.
 * @part .pfx-main - Central content area.
 * @part .pfx-footer - Bottom footer region.
 * @related wrapper
 */
div[class~="pfx-page-layout"] {
  display: flex;
  flex-direction: column;
  min-height: 100vh;
